mapper.select:
select
FROM REP_RAISE_SUM R LEFT JOIN FIN_PRODUCT F ON R.REP_FINPROD_ID = F.FINPROD_ID LEFT JOIN REP_PROD_DECLARE RPD on RPD.REP_FINPROD_ID = R.REP_FINPROD_ID
AND F.FINPROD_MARKET_ID IN
#{item}
AND R.REP_FINPROD_ID IN
#{item}
AND R.REP_FINPROD_REG_ID LIKE CONCAT('%',#{registrationCode},'%')
AND RPD.REP_INVESTOR_TYPE = #{customerType}
AND F.VDATE BETWEEN STR_TO_DATE(#{startDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{startDateEnd},'%Y-%m-%d')
AND R.REP_STATUS_DATE BETWEEN STR_TO_DATE(#{dataDateStart},'%Y-%m-%d') AND STR_TO_DATE(#{dateDateEnd},'%Y-%m-%d')
